{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2153-04-20 18:30:00",
      "speaker": "Doctor",
      "text": "Hello, I’m Dr. Lee. I’ll be your doctor during your stay. You came in today because of pain in your left calf?"
    },
    {
      "turn_number": 2,
      "time": "2153-04-20 18:31:00",
      "speaker": "Patient",
      "text": "Yes, it’s been hurting more since I got back from visiting my mom. It feels tight and really aches when I walk."
    },
    {
      "turn_number": 3,
      "time": "2153-04-20 18:32:00",
      "speaker": "Doctor",
      "text": "I see. And you mentioned some shortness of breath and chest discomfort at night, especially when lying down?"
    },
    {
      "turn_number": 4,
      "time": "2153-04-20 18:33:00",
      "speaker": "Patient",
      "text": "Yes, it’s been worse lately. I get a bit of cough and wheezing at night. But no chest pain during the day."
    },
    {
      "turn_number": 5,
      "time": "2153-04-20 18:34:00",
      "speaker": "Doctor",
      "text": "Given your history of a prior blood clot and recent travel, we’re concerned about a possible clot in your leg or lungs. We’ve done an ultrasound on your legs."
    },
    {
      "turn_number": 6,
      "time": "2153-04-20 18:35:00",
      "speaker": "Patient",
      "text": "Oh, okay. Did they find anything?"
    },
    {
      "turn_number": 7,
      "time": "2153-04-20 18:36:00",
      "speaker": "Doctor",
      "text": "Yes, the ultrasound showed a blood clot in the deep veins of your left calf. That explains the pain and swelling."
    },
    {
      "turn_number": 8,
      "time": "2153-04-20 18:37:00",
      "speaker": "Patient",
      "text": "That sounds serious. Could it have traveled?"
    },
    {
      "turn_number": 9,
      "time": "2153-04-20 18:38:00",
      "speaker": "Doctor",
      "text": "That’s why we ordered a CT scan of your chest. Because of your breathing symptoms, we needed to check for a pulmonary embolism."
    },
    {
      "turn_number": 10,
      "time": "2153-04-20 22:00:00",
      "speaker": "Doctor",
      "text": "The CT scan is back. I’m sorry to say it shows blood clots in the arteries of your right lung. That’s what’s causing your shortness of breath."
    },
    {
      "turn_number": 11,
      "time": "2153-04-20 22:02:00",
      "speaker": "Patient",
      "text": "Oh no… is it dangerous? Are my lungs okay?"
    },
    {
      "turn_number": 12,
      "time": "2153-04-20 22:04:00",
      "speaker": "Doctor",
      "text": "You’re stable right now. No strain on your heart, and your oxygen levels are good. We’re starting you on a blood thinner called Lovenox to prevent more clots."
    },
    {
      "turn_number": 13,
      "time": "2153-04-20 22:06:00",
      "speaker": "Patient",
      "text": "Will I need to be on that forever? I’ve had a clot before."
    },
    {
      "turn_number": 14,
      "time": "2153-04-20 22:08:00",
      "speaker": "Doctor",
      "text": "Given your history of a prior PE and now this new one, it’s likely you’ll need long-term anticoagulation. We’ll discuss that with your oncologist."
    },
    {
      "turn_number": 15,
      "time": "2153-04-21 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Your labs look better today. Your breathing has improved, and you walked the hallway without any drop in oxygen."
    },
    {
      "turn_number": 16,
      "time": "2153-04-21 08:01:00",
      "speaker": "Patient",
      "text": "That’s a relief. I do feel less short of breath."
    },
    {
      "turn_number": 17,
      "time": "2153-04-21 08:03:00",
      "speaker": "Doctor",
      "text": "We’ll discharge you today with Lovenox injections twice a day. You’ll also keep taking your other medications, including prednisone for your GVHD."
    },
    {
      "turn_number": 18,
      "time": "2153-04-21 08:05:00",
      "speaker": "Patient",
      "text": "And my eye drops? I haven’t been using them regularly."
    },
    {
      "turn_number": 19,
      "time": "2153-04-21 08:06:00",
      "speaker": "Doctor",
      "text": "Yes, please restart Systane every hour and Restasis twice a day. Your dry eyes are part of your chronic GVHD and need consistent care."
    },
    {
      "turn_number": 20,
      "time": "2153-04-21 08:08:00",
      "speaker": "Patient",
      "text": "Okay, I’ll try to be better about that. And my headaches?"
    },
    {
      "turn_number": 21,
      "time": "2153-04-21 08:09:00",
      "speaker": "Doctor",
      "text": "You can continue oxycodone as needed, up to every 8 hours. But let your doctor know if they worsen."
    },
    {
      "turn_number": 22,
      "time": "2153-04-21 08:11:00",
      "speaker": "Patient",
      "text": "Will I follow up with my oncologist?"
    },
    {
      "turn_number": 23,
      "time": "2153-04-21 08:12:00",
      "speaker": "Doctor",
      "text": "Yes, definitely. They’ll manage your long-term anticoagulation and GVHD. We’ve sent them all the details."
    },
    {
      "turn_number": 24,
      "time": "2153-04-21 08:14:00",
      "speaker": "Patient",
      "text": "Thank you, Doctor. I feel much better knowing what’s going on."
    },
    {
      "turn_number": 25,
      "time": "2153-04-21 08:15:00",
      "speaker": "Doctor",
      "text": "You’re welcome. We’ll have the discharge papers ready soon. Keep using your medications as prescribed and call if you have chest pain or trouble breathing."
    },
    {
      "turn_number": 26,
      "time": "2153-04-21 10:00:00",
      "speaker": "Doctor",
      "text": "Just a quick check before you leave. How are you feeling?"
    },
    {
      "turn_number": 27,
      "time": "2153-04-21 10:01:00",
      "speaker": "Patient",
      "text": "Good, really. My leg feels better, and I can breathe normally now."
    },
    {
      "turn_number": 28,
      "time": "2153-04-21 10:02:00",
      "speaker": "Doctor",
      "text": "Excellent. Remember to inject Lovenox every 12 hours and follow up with your team. Take care."
    }
  ],
  "summary": {
    "admission_start": "2153-04-20 18:20:00",
    "admission_end": "2153-04-21 17:00:00",
    "summary_paragraph": "The patient was admitted with worsening left calf pain and nighttime respiratory symptoms following recent travel. Imaging confirmed a deep vein thrombosis in the left posterior tibial veins, and a CT angiogram revealed acute pulmonary emboli in the right upper, middle, and lower pulmonary arteries. She remained hemodynamically stable without need for thrombolysis. Anticoagulation with Lovenox was initiated, leading to clinical improvement in respiratory symptoms and ambulatory tolerance. Chronic issues including graft-versus-host disease affecting the eyes, skin, and mouth were managed with ongoing prednisone and eye medications. The patient was discharged home on Lovenox with plans for long-term anticoagulation and follow-up with her oncologist.",
    "problems": [
      "Acute venous embolism and thrombosis of deep vessels of distal lower extremity",
      "Other pulmonary embolism and infarction",
      "Chronic graft-versus-host disease",
      "Chronic myeloid leukemia, in remission",
      "Tear film insufficiency, unspecified",
      "Exposure keratoconjunctivitis",
      "Pain in or around eye",
      "Headache"
    ]
  }
}
